     <script>
       const quizQuestions = [
         {
           id: "question-1",
           title: "Which of these are programming languages commonly used for web development?",
           helpText: "Choose every option that fits. More than one answer is correct.",
           choices: ["JavaScript", "Python", "HTML", "TypeScript"],
         },
         {
           id: "question-2",
           title: "Which languages are primarily compiled before running in many common workflows?",
           choices: ["C++", "Rust", "Ruby", "Go"],
         },
         {
           id: "question-3",
           title: "Which of these languages are known for running on the Java Virtual Machine?",
           choices: ["Java", "Kotlin", "C#", "Scala"],
         },
       ];

       function createElement(tag, props = {}, children = []) {
         const element = document.createElement(tag);

         Object.entries(props).forEach(([key, value]) => {
           if (key === "className") {
             element.className = value;
             return;
           }

           if (key === "text") {
             element.textContent = value;
             return;
           }

           if (key.startsWith("on") && typeof value === "function") {
             element.addEventListener(key.slice(2).toLowerCase(), value);
             return;
           }

           if (value !== undefined && value !== null) {
             element.setAttribute(key, value);
           }
         });

         children.flat().forEach((child) => {
           if (typeof child === "string") {
             element.appendChild(document.createTextNode(child));
           } else if (child) {
             element.appendChild(child);
           }
         });

         return element;
       }

       function ChoiceOption({ questionId, choice, index }) {
         const inputId = `${questionId}-choice-${index + 1}`;

         return createElement("label", { className: "choice", for: inputId }, [
           createElement("input", {
             id: inputId,
             type: "checkbox",
             name: questionId,
             value: choice,
           }),
           createElement("span", { className: "choice-text", text: choice }),
         ]);
       }
